window.OLAYLAR_P0917TARAF = [{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1909-04-19","kesinlik":"gun","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"İstanbul'da Türk-Bulgar Protokolü — Osmanlı Bulgaristan'ın bağımsızlığını tanıdı","gun":"19 Nisan 1909","yer":"İstanbul","yer_id":"Sofya","kisiler":"","d":"Rusya'nın aracılığıyla İstanbul'da imzalanan protokolle Osmanlı Devleti, altı ay önce tek taraflı ilan edilen Bulgaristan bağımsızlığını resmen tanıdı. Böylece Istranca'daki eski Osmanlı-Bulgar sınırı hukuken de iki bağımsız devlet arasındaki hat oldu; bu kesim bugün de Türkiye-Bulgaristan sınırının parçasıdır.","kaynak":"Ş. Doğan, 'Rus Kaynakları Işığında Bulgaristan'ın Bağımsızlık İlanı', Balkan Araştırma Enstitüsü Dergisi 9/2 (2020) s.322 · IBS No. 49 s.9","duygu":["🤝"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1913-11-17","kesinlik":"gun","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"İstanbul Protokolü — Türk-İran sınırının tahdidi","gun":"17 Kasım 1913","yer":"İstanbul","yer_id":"Kasr-ı Şîrîn","kisiler":"","d":"Osmanlı ve İran temsilcileri, İngiliz ve Rus elçilerinin gözetiminde, 1847 Erzurum Antlaşması'na dayanan Türk-İran sınırının tahdit protokolünü İstanbul'da imzaladı. Karma komisyon ertesi yıl Ekim'e kadar hattı Kotur çevresindeki kısa bir kesim dışında yerinde işaretledi. 1923'te Türkiye-İran sınırı olarak kalan bu hat 1932 ve 1937'de üç kesimde değiştirildi.","kaynak":"IBS No. 28 Iran-Turkey (1964) s.5-7 · H. Efe-M. Kızıl, ERZSOSDE X-I (2017) s.77-90","duygu":["🤝"]},{"onem":3,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1915-09-06","kesinlik":"gun","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"Sofya Sözleşmesi — Osmanlı-Bulgar sınırının düzeltilmesi","gun":"6 Eylül 1915 (24 Ağustos Jülyen)","yer":"Sofya","yer_id":"Dimetoka","kisiler":"","d":"Bulgaristan'ın Osmanlı yanında savaşa girmesinden kısa süre önce Sofya'da imzalanan sözleşme, 1913 İstanbul Antlaşması'nın çizdiği Osmanlı-Bulgar sınırını düzeltti. Hattın Doğu Trakya kesimi 1921'de Neuilly komisyonunca yeniden işaretlenip Lozan'da teyit edildi.","kaynak":"IBS No. 49 Bulgaria-Turkey (1965) s.10-12 — 'signed at Sofia, August 24 (September 6), 1915'","duygu":["🤝"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1886-01-01","kesinlik":"yil","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"Fransız-Osmanlı düzenlemesi — Tunus ile Trablusgarp arasındaki sınırın kıyı kesimi çizildi","gun":"1886 (gün kaynakta yok)","yer":"Tunus-Trablusgarp sınırı","yer_id":"","yer_kon":[33.1485,11.5676],"kisiler":"","d":"Tunus'un 1881'de Fransız himayesine girmesinden beş yıl sonra Fransa ile Osmanlı Devleti, Tunus ile Trablusgarp vilayeti arasındaki sınırı Akdeniz kıyısından başlayarak kısa bir mesafe boyunca belirledi. Kaynak yalnız yılı veriyor; hattın koordinatları bilinmiyor.","kaynak":"IBS 121 (1972) s.2 ('An agreement in 1886 between France and Turkey delimited a boundary ... for a limited distance')","duygu":["🤝"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1892-01-01","kesinlik":"yil","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"İkinci Fransız-Osmanlı düzenlemesi — Tunus-Trablusgarp sınırı Gadames'e kadar uzatıldı","gun":"1892 (gün kaynakta yok)","yer":"Tunus-Trablusgarp sınırı","yer_id":"Ğadâmis","kisiler":"","d":"İkinci bir Fransız-Osmanlı düzenlemesi, Tunus ile Trablusgarp vilayeti arasındaki sınırı öncekinden daha ayrıntılı biçimde ve iç kesimde Gadames'e kadar belirledi. Bugünkü sınırı çizen asıl belge on sekiz yıl sonra imzalanacak Trablus Sözleşmesi'dir.","kaynak":"IBS 121 (1972) s.2 ('A second agreement in 1892 delimited the boundary with greater accuracy ... as far as Ghudamis')","duygu":["🤝"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"antlasma","kapsam":"ic","odak_yer":["Refah","Mısır","Taba"],"t":"1906-10-01","kesinlik":"gun","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"Refah Anlaşması — Osmanlı ile Mısır Hidivliği arasındaki Refah-Taba hattı tarif edildi","gun":"1 Ekim 1906","yer":"Refah, Sina","yer_id":"","kisiler":"","d":"1906 Akabe-Taba bunalımının ardından Osmanlı ve Hidiv komiserleri Refah'ta bir idarî ayırma hattı üzerinde anlaştı; hat Akabe Körfezi'ndeki Ras Taba'dan Refah'taki iki sütunun ortasına uzanıyordu. Karma heyet aynı yılın sonu ile ertesi yıl şubatı arasında hat boyunca doksan bir kâgir sütun dikti. Bu hat bugünkü Mısır-İsrail ve Mısır-Gazze sınırıdır.","kaynak":"Taba hakem kararı, RIAA XX (1988) Ek B s.114-116 (anlaşma metni) ve §54-59 (dikim) · IBS 46","duygu":["🤝"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1910-05-19","kesinlik":"gun","k":"antlasma","etiket":["antlasma","diplomasi","konu-diplomasi"],"b":"Trablus Sözleşmesi — Tunus ile Trablusgarp vilayeti arasındaki sınır Ras Ecdir'den Gadames'e çizildi","gun":"19 Mayıs 1910 (kaynaklar arası 12/19 Mayıs ikiliği var)","yer":"Trablus / Tunus-Trablusgarp sınırı","yer_id":"Trablus","kisiler":"","d":"Fransa ile Osmanlı Devleti arasında Trablus'ta imzalanan sözleşme, Tunus ile Trablusgarp vilayeti arasındaki sınırı Akdeniz kıyısındaki Ras Ecdir'den Gadames'in güneyine kadar tarif etti. Karma komisyon 1910-1911'de hattı iki yüzü aşkın taşla işaretledi; hat bugün de Libya-Tunus sınırıdır. Bu sınır iki yıl sonra Uşi Antlaşması'yla Osmanlı'dan İtalya'ya geçti.","kaynak":"IBS 121 (1972) s.2-5 · Martens, Nouveau Recueil Général 3. seri c.VII s.91-93 · IBS 001 (1961) s.2, s.6 ('12 May 1910')","duygu":["🤝"]}];

