window.OLAYLAR_0073_IRAN_YANYA = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"savas","kapsam":"ic","t":"1821-01-01","gs":10,"k":"savas","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Osmanlı-İran savaşı başladı — Kars ve Bayazıt'ın kaybı, Erzurum'un kuşatılması","gun":"1821 sonbaharı","yer":"Kars, Bayazıt, Erzurum","yer_id":"Erzurum","kisiler":"Veliaht Abbas Mirza, II. Mahmud","d":"Yunan isyanının ikinci yılında imparatorluğun doğu sınırı bir savaş bölgesine döndü. Kaçar veliahdı Abbas Mirza, şahın hacca giden hanımının bulunduğu kervanın Osmanlı temsilcilerince aranmasını bahane ederek büyük bir askerî kuvvetle sınırı geçti; Kars ve Bayazıt vilâyetlerini ele geçirdi ve Erzurum'u kuşatma altına aldı. Karşısındaki kuvvet sıradan bir sınır birliği değildi: Abbas Mirza Azerbaycan ordusunu Avrupa usullerine göre eğitmiş, Tebriz'de barut imalâthanesi ve top tezgâhları kurdurmuştu. Osmanlı Devleti ise bu sırada batıda Mora isyanıyla, kuzeybatıda Tepedelenli Ali Paşa'nın Yanya'daki direnişiyle uğraşıyordu ve elinde Avrupa usulünde eğitilmiş bir ordu yoktu; Yeniçeri Ocağı 1826'ya kadar ayakta kalacaktı.","kaynak":"iran (TDV) · abbas-mirza (TDV) · kars (TDV, bu yıllar hakkında sessiz — teyit için okundu)","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1821-01-01","gs":20,"k":"kayip","etiket":["toprak-kayip","savas","konu-askeri"],"b":"Süleymaniye ve Bağdat'ın İran işgali — Kerkük muhasarası","gun":"1821","yer":"Bağdat, Süleymaniye, Kerkük, Kuzey Irak","yer_id":"Bağdat","kisiler":"Kölemen Dâvud Paşa","d":"Doğu Anadolu'daki harekâtla eş zamanlı olarak İran kuvvetleri Osmanlı idaresindeki Kuzey Irak ve Bağdat eyaletine geniş çaplı bir saldırı düzenledi. Bağdat'ı o sırada, 1817'den beri valilik yapan Kölemen Dâvud Paşa yönetiyordu; paşa Napolyon'un eski yaverlerinden Deveaux'ya tâlim ettirdiği 10.000 kişilik piyade ve topçu kuvvetine sahipti. İmparatorluğun merkezinde henüz böyle bir ordu yoktu — Avrupa usulünde eğitilmiş birlikler o yıllarda ancak taşradaki güçlü valilerin elindeydi. Savaşı bitiren şey bir Osmanlı zaferi olmadı: Osmanlı direnişi ve Azerbaycan'ı saran salgın hastalık İran kuvvetlerini geri çekilmeye mecbur bıraktı.","kaynak":"iran (TDV) · bagdat (TDV — savaşı doğruluyor, işgali anmıyor) · kerkuk (TDV, bu yıllar hakkında sessiz)","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"antlasma","kapsam":"ic","t":"1823-07-28","k":"antlasma","etiket":["antlasma","konu-diplomasi"],"antlasma_id":"erzurum-1823","b":"Erzurum Antlaşması — İran kuvvetlerinin altmış günde çekilmesi","gun":"28 Temmuz 1823","yer":"Erzurum","yer_id":"Erzurum","kisiler":"II. Mahmud, Feth Ali Şah","d":"İki yıl süren savaş, Erzurum'da imzalanan barış antlaşmasıyla sona erdi. Antlaşma uyarınca İran kuvvetleri altmış gün içinde işgal ettikleri topraklardan çekilecekti. Antlaşma yeni bir sınır çizmedi, savaş öncesi durumu geri getirdi; iki devlet arasındaki sınır anlaşmazlıkları 1833-1842'de yeniden çatışmaya dönüşecek ve ancak 1847'de, yine Erzurum'da imzalanan ikinci bir antlaşmayla düzenlenecekti. Doğu cephesinin kapanması, imparatorluğun bütün ağırlığını Yunan isyanına verebilmesinin ön şartıydı.","kaynak":"iran (TDV)","duygu":["🏛"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1820-03-01","k":"siyaset","etiket":["siyaset","ayaklanma","konu-siyasi","konu-askeri"],"b":"Tepedelenli Ali Paşa'nın azli ve Yanya kuşatmasının başlaması","gun":"Mart 1820","yer":"Yanya (Epir), Tepedelen","yer_id":"Yanya","kisiler":"Tepedelenli Ali Paşa, Hurşid Ahmed Paşa, Hâlet Efendi, II. Mahmud","d":"II. Mahmud'un mahallî güçleri tasfiye siyaseti, otuz üç yıldır Yanya'yı yöneten ve Tesalya ile Epir'i fiilen elinde tutan Tepedelenli Ali Paşa'ya ulaştı. Paşa derbendler başbuğluğundan, oğlu Veli de Tırhala paşalığından azledildi; buna uymayacağı beklendiğinden üzerine kuvvet sevkedildi. Bu işle görevlendirilen Hurşid Ahmed Paşa aynı zamanda Mora valisiydi ve ona Rumeli seraskerliği de verilmişti; bölgedeki bütün mülkî ve askerî yöneticiler Tepedelenli'yi yakalamakla görevlendirildi. Yani Yunan isyanı patladığında Mora'yı yönetmesi gereken kumandan ve emrindeki kuvvetler Yanya Kalesi'ni kuşatıyordu. Ali Paşa 23 Mayıs 1820'de Rumlarla Yanya'da bir toplantı düzenledi, kendi idaresinde bir Rum eyaleti kurmaya tevessül etti ve onlara para ile silâh yardımında bulundu. Karşı tarafta küçümsenecek bir güç yoktu: Ali Paşa'nın 7.000'i dâimî olmak üzere 30-40.000 kişilik bir ordusu ve küçük bir donanması vardı; idaresindeki nüfus 1,5-2 milyon, yıllık geliri 4-5 milyon kuruş tahmin ediliyordu.","kaynak":"tepedelenli-ali-pasa (TDV, Kemal Beydilli) · hursid-ahmed-pasa (TDV, Cevdet Küçük) · yunanistan (TDV, Mehmet Hacısalihoğlu)","duygu":["🏛"]},{"onem":4,"dunya":2,"bolge_onem":3,"puan_s":"v2","tur":"isyan","kapsam":"ic","t":"1822-02-14","k":"isyan","etiket":["ayaklanma","konu-askeri","konu-isyan","konu-kisiler"],"b":"Tepedelenli Ali Paşa'nın öldürülmesi — Yanya kuşatmasının sonu","gun":"14 Şubat 1822","yer":"Yanya gölü, Pandeleimon Manastırı","yer_id":"Yanya","kisiler":"Tepedelenli Ali Paşa, Hurşid Ahmed Paşa, Köse Mehmed Paşa","d":"Yanya'daki direniş iki yıla yakın sürdü ve tam bu süre içinde Rum isyanı genel bir yaygınlık kazandı. Hurşid Paşa kaleye casuslar gönderip kaçanlara rütbe ve atıyye dağıtınca Ali Paşa'nın etrafındaki asker sayısı kırk elli kişiye düştü; paşa teslim olması hâlinde canına dokunulmayacağı teminatıyla göl üzerindeki Pandeleimon Manastırı'na çekildi. Bu sırada Hurşid Paşa'nın ailesi Rum isyancıların eline geçmişti; bir an önce Mora'ya dönebilmek için verdiği emannâmeyi yok sayıp düzmece bir idam fermanı hazırlattı. Odasına girildiğinde Ali Paşa silâhla karşılık verdi ve çıkan çatışmada öldürüldü; başı 24 Şubat'ta İstanbul'a getirildi. Kuşatma Osmanlı kumandasının kendi içindeki çatlağı da açığa çıkarmıştı: Mora isyanı Tepedelenli meselesinden tehlikeli hâle gelince Seyyid Ali Paşa müstakil Mora seraskeri tayin edilmiş, bundan hoşlanmayan Hurşid Paşa onun yardım isteklerini geri çevirmiş, hatta onu devlet nazarında başarısız göstermeye çalışmıştı. Ali Paşa'nın ortadan kaldırıldığı yılın sonunda Mora'nın en güçlü kalesi Anabolu düştü.","kaynak":"tepedelenli-ali-pasa (TDV, Kemal Beydilli) · hursid-ahmed-pasa (TDV, Cevdet Küçük)","duygu":["😔"]}];

