window.OLAYLAR_DUNYA_BOLGE_1109 = [{"kapsam":"dis","bolge":4,"t":"1405-02-18","k":"taht","odak_yer":["Otrar"],"tur":"hanedan","etiket":["siyaset"],"b":"Timur öldü","d":"Timur'un Çin seferi yolunda ölümü, İmparatorluğunun oğulları ve torunları arasında paylaşılmasına yol açtı; İran'ın büyük bölümü sonunda oğlu Şahruh'un elinde birleşti, başşehir Herat'a taşındı.","kaynak":"timur (TDV, doğrulanmış)","onem":3,"dunya":2,"gun":"18 Şubat 1405"},{"kapsam":"dis","bolge":4,"t":"1439-07-06","k":"diplomasi","tur":"din","etiket":["diplomasi"],"b":"Floransa birliği ilan edildi","d":"Ortodoks ve Katolik kiliselerinin birleştiği ilan edildi; imza atmayan tek piskopos Efesli Markos oldu. Bizans anlatısında birlik, devleti kurtarmak için inancın satılması olarak algılandı ve halk tarafından reddedildi: \"Latin serpuşu yerine Türk sarığı\" sözü bu yılların ürünüdür.","kaynak":"TDV İslâm Ansiklopedisi, «Bizans» https://islamansiklopedisi.org.tr/bizans — «Floransa'da ilân edilen (6 Temmuz 1439) union hiçbir fayda sağlamadı» ; el-kitabi","yer_id":"Floransa","onem":5,"dunya":3,"gun":"6 Temmuz 1439"},{"kapsam":"dis","bolge":4,"t":"1458-01-24","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Hunyadi Mátyás'ın (Mátyás Corvinus) kral seçilmesi","d":"Buda'yı çevreleyen buzlu Tuna üzerinde toplanan soylu ve halk kitlesi, on beş yaşındaki Mátyás'ı kral ilan etti; bu, yabancı bir hanedan yerine 'yerli' bir soylu ailenin tahta çıktığı istisnaî bir andı. Otuz iki yıllık saltanatı Macaristan'ı Orta Avrupa'nın en güçlü devletlerinden birine dönüştürecekti.","kaynak":"akademik: Engel (2001), s. 301-303","yer_id":"Aquincum-Óbuda-Pest","onem":5,"dunya":2,"gun":"24 Ocak 1458"},{"kapsam":"dis","bolge":4,"t":"1490-04-06","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Mátyás Corvinus'un ölümü","d":"Meşru varis bırakmadan ölen Mátyás'ın ardından merkezîleşme siyaseti çöktü; Fekete Ordu dağıtıldı, soylular güçlerini geri kazandı ve taht zayıf bir Jagiellon kralına, II. Ulászló'ya geçti. Çağdaşları bu ölümü Macaristan'ın 'altın çağının' sonu olarak andı.","kaynak":"akademik: Engel (2001), s. 345-347","yer_id":"Viyana","onem":5,"dunya":3,"gun":"6 Nisan 1490"},{"kapsam":"dis","bolge":4,"t":"1492-03-31","k":"kanun","tur":"hukuk","etiket":["siyaset"],"b":"Alhambra Fermanı — Yahudilerin sürgünü","d":"İsabel ve Fernando, hıristiyanlığa dönmeyen bütün Yahudilerin dört ay içinde ülkeyi terk etmesini emretti; 40.000-100.000 arası kişi (tahminler değişir) Portekiz, Kuzey Afrika ve Osmanlı topraklarına göç etti. Sultan II. Bayezid'in donanma göndererek göçmenleri taşıttığı rivayeti bu olayla aynı dalgaya aittir.","kaynak":"standart akademik kaynak (Kamen, Spain 1469-1714) — imparatorluk çapında ferman, tek bir yerleşime bağlanamaz","odak_yer":["Granada"],"onem":5,"dunya":4,"gun":"31 Mart 1492"},{"kapsam":"dis","bolge":4,"t":"1519-06-28","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Şarlken, Kutsal Roma İmparatoru seçildi","d":"Frankfurt'taki seçmenler kurulu, Fransa kralı I. François'ya karşı İspanya kralı Şarlken'i imparator seçti; böylece İspanya, Almanya, Hollanda, Burgonya ve İtalya'nın büyük kısmını kapsayan bir kişisel birliğin merkezi oldu. Seçim, Şarlken'in İspanya'dan uzun süre uzak kalmasına ve ağır vergi taleplerine yol açarak Comuneros isyanını tetikledi.","kaynak":"standart akademik kaynak (Kamen, Spain 1469-1714)","yer_id":"Frankfurt","onem":5,"dunya":4,"gun":"28 Haziran 1519"},{"kapsam":"dis","bolge":4,"t":"1524-05-23","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Şah İsmail öldü, I. Tahmasb tahta çıktı","d":"Çaldıran'ın ardından içine kapanan Şah İsmail'in ölümüyle on yaşındaki oğlu Tahmasb tahta çıktı; ilk on yılı Kızılbaş boy liderleri arasındaki naiplik kavgalarıyla geçti, ama 54 yıllık saltanatı Safevî devletinin en uzun sürenlerinden biri oldu.","kaynak":"safeviler (TDV, doğrulanmış)","yer_id":"Tebriz","onem":3,"dunya":1,"gun":"23 Mayıs 1524"},{"kapsam":"dis","bolge":4,"t":"1552-10-02","k":"kayip","tur":"toprak","etiket":["toprak-kayip"],"b":"Kazan'ın düşüşü — Orta İdil'de dokuz asırlık Türk hâkimiyeti bitti","d":"İki ay kadar süren kanlı çarpışmaların ardından 2 Ekim 1552'de (Jülyen; Gregoryen karşılığı 12 Ekim — TDV'nin «15 Ekim»i 13 günlük çeviri farkı görünümünde) Kazan düştü ve Orta İdil sahasında milâttan sonra VI. yüzyıldan beri süren Türk hâkimiyeti sona erdi. Şehrin sanat, hat ve yapı eserleri yağma edildi; büyük çoğunluğunun izi bile kalmadı.","kaynak":"kazan-hanligi (TDV — '15 Ekim 1552'de Kazan düştü')","yer_id":"Kazan","onem":5,"dunya":4,"gun":"15 Ekim 1552"},{"kapsam":"dis","bolge":4,"t":"1556-01-01","k":"kayip","tur":"toprak","etiket":["toprak-kayip"],"b":"Astrahan Hanlığı ilhak edildi","d":"Kazan'ın düşmesinden dört yıl sonra Astrahan Hanlığı da ilhak edildi; böylece Volga Nehri'nin tamamı ve Hazar Denizi'ne çıkış Rusya'nın eline geçti. Bu iki fetih, Rusya'nın güneye ve doğuya (Sibirya'ya) genişlemesinin coğrafi anahtarını oluşturdu.","kaynak":"Riasanovsky & Steinberg, A History of Russia — devletler.js:286'dan taşındı, doğrulandı","yer_id":"Astrahan","onem":4,"dunya":3,"gun":"1556"},{"kapsam":"dis","bolge":4,"t":"1576-05-14","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"I. Tahmasb öldü — veraset krizi başladı","d":"I. Tahmasb'ın ölümüyle oğulları arasında kanlı bir taht kavgası patlak verdi; on yıl süren bu istikrarsızlık (İsmail II ve Muhammed Hüdâbende dönemleri) Kızılbaş iç çekişmelerini derinleştirdi ve Osmanlı'ya yeni bir savaş fırsatı doğurdu.","kaynak":"Encyclopaedia Iranica, madde: ṬAHMĀSP I","yer_id":"Kazvin","onem":3,"dunya":1,"gun":"14 Mayıs 1576"},{"kapsam":"dis","bolge":4,"t":"1587-10-01","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"I. Şah Abbas tahta çıktı","gun":"Ekim 1587 — ay hassasiyeti (TDV `abbas-i`: \"Safevî tahtına oturttu (Ekim 1587)\"; `safeviler` hükümdar listesi: Abbas I 995 (1587))","d":"On yedi yaşındaki Abbas, babası Muhammed Hüdâbende'nin yerine Kızılbaş emîrlerince tahta çıkarıldı; 42 yıllık saltanatı Safevî devletinin askerî, idari ve kültürel zirvesi olacaktı. İran tarihyazımında Şah Abbas dönemi, Rusya'nın Petro'su veya Osmanlı'nın Kanûnî'si düzeyinde bir \"altın çağ\" referans noktasıdır.","kaynak":"safeviler (TDV, doğrulanmış) · abbas-i (TDV: Ekim 1587 — eski kayıt 1588 diyordu; çelişkide TDV esas alındı)","yer_id":"Kazvin","onem":4,"dunya":3},{"kapsam":"dis","bolge":4,"t":"1629-01-19","k":"taht","odak_yer":["Ferahâbâd","Eşref (Behşehr)","Sârî"],"tur":"hanedan","etiket":["siyaset"],"b":"Şah Abbas öldü","d":"Kırk iki yıllık saltanatının ardından Şah Abbas'ın ölümü, Safevî devletinin zirve döneminin kapanışı sayılır; yerine geçen torunu Şah Safi'nin dönemiyle birlikte yavaş ama kesintisiz bir gerileyiş süreci başladı.","kaynak":"Encyclopaedia Iranica, madde: ʿABBĀS I","onem":4,"dunya":2,"gun":"19 Ocak 1629"},{"kapsam":"dis","bolge":4,"t":"1709-07-08","k":"savas","tur":"savas","etiket":["savas"],"b":"Poltava — Mazepa ve XII. Karl yenildi, Hetmanlığın kaderi mühürlendi","gun":"8 Temmuz 1709 (Gregoryen — TDV `ukrayna` ve EoU aynı günü verir; Jülyen 27 Haziran — Rusya kronolojisi o günü yazar)","d":"Ukrayna topraklarında süren 1708-1709 Rus-İsveç savaşı Poltava'da müttefiklerin yenilgisiyle bitti; Mazepa, Orlik ve Kazak taraftarları XII. Karl ile birlikte Osmanlı topraklarına, Bender'e sığındı. EoU'ya göre bu yenilgi Ukrayna'nın kaderini mühürledi; Petro bundan sonra Hetmanlığın özerkliğini adım adım daralttı.","kaynak":"TDV `ukrayna` (8 Temmuz 1709) · Encyclopedia of Ukraine (CIUS), «Mazepa, Ivan» (8 Temmuz 1709)","yer_id":"Poltava","onem":5,"dunya":4},{"kapsam":"dis","bolge":5,"t":"1722-10-25","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Mahmud Hotakî'nin şah ilan edilmesi","d":"İsfahan'ın teslim alınmasının hemen ardından Mahmud, kendini İran şahı ilan etti; bir Sünni Afgan liderinin Şiî İran tahtına çıkışı, İran tarihyazımında ülkenin \"yabancı işgali\" olarak anılan kısa ama travmatik Hotakî döneminin (1722-1729) başlangıcıdır.","kaynak":"Encyclopaedia Iranica, madde: MAḤMUD ḠALZAY","yer_id":"Isfahan","onem":4,"dunya":3,"gun":"25 Ekim 1722"},{"kapsam":"dis","bolge":4,"t":"1762-07-09","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"II. Katerina darbeyle tahta çıktı","d":"Alman asıllı çariçe Katerina, muhafız subaylarının (bir kısmı âşığı) desteğiyle eşi III. Petro'yu devirip tahta çıktı; Petro birkaç gün sonra şüpheli koşullarda öldürüldü. 34 yıllık saltanatı Rusya'nın toprak olarak en büyük genişlemesine ve \"Aydınlanmış Otokrasi\" söylemine sahne oldu.","kaynak":"Riasanovsky & Steinberg, A History of Russia","yer_id":"St. Petersburg","onem":4,"dunya":1,"gun":"9 Temmuz 1762"},{"kapsam":"dis","bolge":4,"t":"1783-08-04","k":"antlasma","tur":"antlasma","etiket":["antlasma"],"b":"Georgievsk Antlaşması — Kartli-Kaheti Rusya himayesine girdi","d":"II. Herakli, Osmanlı ve İran baskısına karşı güvence arayışıyla Rusya ile bir himaye antlaşması imzaladı; Kartli-Kaheti dış politikasını Rusya'ya devretti ve karşılığında askerî koruma vaadi aldı. Bu antlaşma, on sekiz yıl sonraki tam ilhakın hukuki zeminini hazırladı.","kaynak":"devletler.js gurcistan künyesi (TDV, önceden doğrulanmış)","yer_id":"Tiflis","onem":5,"dunya":3,"gun":"4 Ağustos 1783"},{"kapsam":"dis","bolge":4,"t":"1813-10-24","k":"antlasma","odak_yer":["Tiflis","Gence","Bakü","Şuşa"],"tur":"antlasma","etiket":["antlasma"],"b":"Gülistan Antlaşması — Kafkasya'nın büyük kısmı kaybedildi","d":"İran, Gürcistan, Dağıstan ve Kuzey Azerbaycan'ın (Bakü, Şirvan, Karabağ, Gence dahil) tamamı üzerindeki hak iddialarından vazgeçti; Hazar Denizi'nde donanma bulundurma hakkını da kaybetti. İran tarihyazımında bu antlaşma, ülkenin bugün de hissedilen \"kaybedilen Kafkasya\" travmasının hukuki başlangıcıdır — dünya ölçeğinde de Rusya'nın Transkafkasya'daki kalıcı hâkimiyetini tesis eden, bölgenin siyasi haritasını yeniden çizen bir antlaşmadır.","kaynak":"azerbaycan (TDV, doğrulanmış — bu turda ayrıca sınandı: gulistan-antlasmasi slug'ı ARAMA SAYFASI çıktı, madde değil, dosya başı notuna bkz.) + Encyclopaedia Iranica, madde: GOLESTAN TREATY","onem":5,"dunya":4,"gun":"24 Ekim 1813"},{"kapsam":"dis","bolge":4,"t":"1906-08-05","k":"reform","tur":"siyaset","etiket":["siyaset"],"b":"Muzafferüddin Şah anayasayı imzaladı — Meşrutiyet ilan edildi","d":"Ölümünden birkaç hafta önce Muzafferüddin Şah, ilk Millet Meclisi'nin (Meclis-i Şûrâ-yı Millî) toplanmasını ve bir anayasa hazırlanmasını onayladı; İran böylece Osmanlı'dan (1876/1908) ve Rusya'dan (1905) bağımsız olarak kendi anayasal deneyimine başladı. İran tarihyazımında bu, 1979 Devrimi kadar olmasa da modern İran siyasi tarihinin en köklü dönüm noktalarından biridir — dünya ölçeğinde de Asya'daki anayasacılık dalgasının (Japonya 1889, Osmanlı 1908, Rusya 1905/1906) bir parçası olarak bölgesel/küresel bir sistemik eğilimi yansıtır.","kaynak":"mesrutiyet (TDV, doğrulanmış)","yer_id":"Tahran","onem":5,"dunya":3,"gun":"5 Ağustos 1906"},{"kapsam":"dis","bolge":5,"t":"1907-08-31","k":"antlasma","tur":"antlasma","etiket":["antlasma"],"b":"1907 İngiliz-Rus Antlaşması — İran nüfuz bölgelerine bölündü","d":"İngiltere ve Rusya, İran'ın rızası alınmadan ülkeyi kuzeyde Rus, güneydoğuda İngiliz nüfuz bölgesi ve ortada tarafsız bir kuşak olmak üzere fiilen üçe böldü; bu antlaşma \"Büyük Oyun\"un resmî sonu ve İran egemenliğinin iki büyük güç tarafından açıkça hiçe sayıldığı, ülkenin bağımsızlığına en ağır darbelerden biri sayılır — aynı zamanda dünya sisteminde İngiliz-Rus rekabetini WWI öncesi ittifak yapısına (Fransa-Rusya-İngiltere) doğru kaydıran bölgesel bir güç dengesi antlaşmasıdır.","kaynak":"Encyclopaedia Iranica, madde: ANGLO-RUSSIAN CONVENTION OF 1907","odak_yer":["Tebriz","Meşhed","Kirman","Bender Abbas (Gamrûn)"],"onem":4,"dunya":4,"gun":"31 Ağustos 1907"},{"kapsam":"dis","bolge":5,"t":"1917-03-15","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"II. Nikolay tahttan çekildi, Romanov hanedanı sona erdi","d":"II. Nikolay, kendisi ve oğlu adına tahttan çekildiğini ilan etti; kardeşi Mihail'in de ertesi gün tacı kabul etmeyi reddetmesiyle 1613'ten beri 304 yıl süren Romanov hanedanı ve üç yüzyıllık otokratik monarşi resmen sona erdi. Rus tarihyazımında Kulikovo, 1613, 1812 ve 1861 ile aynı düzeyde, imparatorluk döneminin kapanış tarihidir (bkz. [[rusya-gecici-hukumet]], [[sovyet-rusya]]).","kaynak":"Riasanovsky & Steinberg, A History of Russia — devletler.js:299'dan taşındı, doğrulandı","yer_id":"Pskov","onem":5,"dunya":4,"gun":"15 Mart 1917"},{"kapsam":"dis","bolge":5,"t":"1917-11-02","k":"diplomasi","tur":"diplomasi","etiket":["diplomasi"],"b":"Balfour Deklarasyonu yayımlandı","d":"Dışişleri Bakanı Arthur Balfour, Filistin'de Yahudiler için bir 'millî yurt' kurulmasına Britanya hükümetinin desteğini bildiren bir mektubu Lord Rothschild'e gönderdi. Deklarasyon, sonraki bir asır boyunca Orta Doğu'nun siyasî tarihini derinden şekillendirecek bir taahhüt oldu.","kaynak":"Avalon Project (Yale Law School), «Balfour Declaration November 2, 1917» https://avalon.law.yale.edu/20th_century/balfour.asp — «Balfour Declaration 1917 November 2nd, 1917 Dear Lord Rothschild» ; el-kitabi","yer_id":"Londra","onem":5,"dunya":4,"gun":"2 Kasım 1917"},{"kapsam":"dis","bolge":5,"t":"1917-11-07","k":"darbe","tur":"siyaset","etiket":["siyaset"],"b":"Ekim Devrimi — Bolşevikler Rusya Geçici Hükûmeti'ni devirdi","d":"Lenin önderliğindeki Bolşevikler, Petrograd'da Geçici Hükûmet'i devirerek iktidarı ele geçirdi (Jülyen takvimiyle 25 Ekim, bu yüzden \\\"Ekim Devrimi\\\").","kaynak":"Riasanovsky & Steinberg, A History of Russia","yer_id":"St. Petersburg","onem":5,"dunya":5,"gun":"7 Kasım 1917"},{"kapsam":"dis","bolge":4,"t":"1385-08-14","k":"diplomasi","tur":"diplomasi","etiket":["diplomasi"],"b":"Krewo birliği — Polonya ile Litvanya'nın birleşmesi","d":"Litvanya Büyük Dükü Jogaila, Jadwiga ile evlenmek, Hristiyanlığı kabul etmek ve Litvanya'yı Polonya tacına bağlamak taahhüdünde bulundu. Polonya ulusal anlatısında Krewo, Avrupa'nın en büyük devletlerinden birini doğuran kurucu belgedir; bir savaşla değil bir evlilik akdiyle kurulan birlik olarak özellikle vurgulanır.","kaynak":"el-kitabi","yer_kon":[54.3103,26.2864],"onem":5,"dunya":4,"gun":"14 Ağustos 1385"},{"kapsam":"dis","bolge":4,"t":"1400-10-30","k":"savas","tur":"savas","etiket":["savas"],"b":"Halep'in düşüşü — Memlük ordusu bozguna uğradı","gun":"30 Ekim 1400 — meydan savaşı ve şehre giriş (Cengiz 2020); Halep Kalesi daha sonra düştü, günü verilmiyor · eski t 1400-10-01 ay başı yer tutucuydu","d":"Hindistan seferinden dönen Timur, 'Yedi Yıllık Sefer' adı verilen batı harekâtı kapsamında Suriye'ye girip Halep önünde Memlük ordusunu yendi; şehir üç gün yağmalandı ve kafataslarından kuleler yapıldı. Halep'in düşüşü, Kahire'deki Memlük sarayında paniğe yol açan ilk büyük darbeydi.","kaynak":"TDV `timur`: \"Suriye’de Halep, Hama, Humus ve Dımaşk gibi şehirleri aldı.\" (cümle TARİHSİZ) · TDV `timurlular`: \"Timur, 1399-1400 döneminde Memlükler’i ve ardından Osmanlılar’ı yendi\" · gün: bulunamadı — TDV gün vermiyor. Önceki tırnaklı \"1400-1401: …\" cümlesi TDV gövdesinde YOK, kaldırıldı · daha önce künyede 1400-01-01 \"Halep ve Şam'ı ele geçirdi\" yazılıydı, kaynaksız (yıl hassasiyeti); mükerrer olarak kaldırıldı · gün: Ercan Cengiz, \"Timur’un Suriye Seferi\", Kafkas Üniversitesi SBE Dergisi 26 (2020), DOI 10.9775/kausbed.2020.034: \"Memluk kuvvetleri 30 Ekim’de şehrin dışına çıkarak Timur’un ordusuna doğru saldırıya geçtiler\" … \"Timur’un ordusu Halep’e girerek şehri yağmaladı\" — cümleler meydan savaşını ve şehre girişi tarihliyor","yer_id":"Halep","onem":4,"dunya":3},{"kapsam":"dis","bolge":4,"t":"1480-11-11","k":"savas","tur":"savas","etiket":["savas"],"b":"Ugra Nehri'nde karşı karşıya gelme — Tatar boyunduruğunun bitişi","d":"III. İvan'ın orduları ile Büyük Orda hanı Ahmed'in kuvvetleri Ugra Nehri kıyısında aylarca karşı karşıya durdu; çatışma olmadan Ahmed geri çekildi. Rus tarihyazımı bu olayı \"Tatar boyunduruğunun\" (1237'den beri süren) resmî ve kesin sonu, Moskova'nın bağımsız bir güç olarak doğuşu sayar — Kulikovo kadar, bazı tarihçilere göre ondan da fazla, dönüm noktasıdır.","kaynak":"Riasanovsky & Steinberg, A History of Russia","yer_kon":[54.57,36.05],"onem":5,"dunya":3,"gun":"11 Kasım 1480"},{"kapsam":"dis","bolge":4,"t":"1556-01-16","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Şarlken'in tahttan çekilmesi — İspanya tacı II. Felipe'ye geçti","d":"Şarlken, Brüksel'de düzenlenen törenle İspanya ve Hollanda tacını oğlu Felipe'ye devretti; imparatorluk unvanını ise kardeşi Ferdinand'a bıraktı. Bu ayrım, Habsburg hanedanının Avusturya ve İspanya kollarının bundan böyle ayrı yürüyeceğinin ilanıydı.","kaynak":"standart akademik kaynak (Kamen, Spain 1469-1714)","yer_kon":[50.8466,4.3528],"onem":5,"dunya":3,"odak_yer":["Brüksel"],"gun":"16 Ocak 1556"},{"kapsam":"dis","bolge":4,"t":"1613-03-03","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"Romanov hanedanı tahta çıktı","d":"Zemski Sobor, on altı yaşındaki Mihail Romanov'u çar seçti; böylece on beş yıllık Karışıklıklar Dönemi resmen kapandı ve 1917'ye kadar sürecek Romanov hanedanı başladı. Rus ulusal tarihyazımında devletin ve toplumsal düzenin yeniden kurulmasının, Smuta'nın kapanışının dönüm tarihidir.","kaynak":"Riasanovsky & Steinberg, A History of Russia — devletler.js:288'den taşındı, doğrulandı","yer_id":"Moskova","onem":5,"dunya":2,"gun":"3 Mart 1613"},{"kapsam":"dis","bolge":4,"t":"1648-05-16","k":"savas","tur":"savas","etiket":["savas"],"b":"Hmelnitski ayaklanması başladı — Sarı Sular","d":"Kazak hatmanı Bohdan Hmelnitski'nin Kırım Tatarlarıyla ittifak kurarak başlattığı ayaklanma, Sarı Sular'da bir Polonya kuvvetini imha etti ve on gün sonra Korsun'da ordunun ana gövdesini yok etti. Polonya tarihyazımı bu tarihi altın çağın bittiği an olarak alır: cumhuriyet bir daha eski gücüne dönemedi.","kaynak":"kazaklar","yer_kon":[48.35,33.5],"onem":5,"dunya":4,"odak_yer":["Kiev","Çehrin (Çigirin)"],"gun":"16 Mayıs 1648"},{"kapsam":"dis","bolge":4,"t":"1805-12-02","k":"savas","tur":"savas","etiket":["savas"],"b":"Austerlitz — Üç İmparator Muharebesi","d":"Ruslar ve Avusturyalılar Austerlitz'te kesin biçimde yenildi. Ardından gelen Pressburg Barışı ağır toprak kayıpları getirdi: Venedik, İstriya ve Dalmaçya Fransa'ya, bütün Ön Avusturya Bavyera'ya geçti — yaklaşık üç milyon nüfus.","kaynak":"Die Welt der Habsburger, 'Kaiser Franz II./I. und Napoleon': Austerlitz sonrası Pressburg Barışı, 1000 kare mil / üç milyon nüfus kaybı, Venedik-İstriya-Dalmaçya Fransa'ya, Ön Avusturya Bavyera'ya","yer_kon":[49.0667,16.8667],"onem":4,"dunya":4,"odak_yer":["Brno","Viyana"],"gun":"2 Aralık 1805"},{"kapsam":"dis","bolge":4,"t":"1921-02-21","k":"darbe","tur":"siyaset","etiket":["siyaset"],"b":"Rıza Han'ın darbesi","d":"Kazak Tugayı komutanı Rıza Han, gazeteci Seyyid Ziyâeddin Tabâtabâî ile birlikte Tahran'ı ele geçirip yeni bir hükûmet kurdu; ilk aşamada Ahmed Şah'ı tahtta bıraksa da fiilî iktidarı ele geçirdi. İran tarihyazımında bu, Kaçar hânedanının fiilî sonunun ve Pehlevî dönemine geçişin başlangıç tarihidir.","kaynak":"Encyclopaedia Iranica, madde: REZA SHAH","yer_id":"Tahran","onem":4,"dunya":2,"gun":"21 Şubat 1921"},{"kapsam":"dis","bolge":4,"t":"1905-01-22","k":"ayaklanma","tur":"siyaset","etiket":["siyaset"],"b":"Kanlı Pazar","d":"Papaz Gapon önderliğinde barışçıl bir dilekçe yürüyüşü düzenleyen işçi kalabalığı, Kışlık Saray önünde çariçenin muhafızlarınca ateş açılarak dağıtıldı; yüzlerce kişi öldü. Rus tarihyazımında bu katliam, halkın çara duyduğu geleneksel \"baba çar\" güveninin kesin biçimde kırıldığı ve 1905 Devrimi'nin fiilen başladığı tarihtir.","kaynak":"Riasanovsky & Steinberg, A History of Russia","yer_id":"St. Petersburg","onem":4,"dunya":1,"gun":"22 Ocak 1905"},{"kapsam":"dis","bolge":4,"t":"1815-09-26","k":"antlasma","tur":"antlasma","etiket":["antlasma"],"b":"Kutsal İttifak — Rusya, Avusturya ve Prusya hükümdarları Paris'te birleşti","gun":"26 Eylül 1815 (Jülyen 14 Eylül)","yer_id":"Paris","odak_yer":["Paris","Viyana","Berlin"],"d":"Napolyon'un yenilgisinden sonra Rus Çarı I. Aleksandr, Avusturya İmparatoru I. Franz ve Prusya Kralı III. Friedrich Wilhelm, Hristiyan ilkelerine göre yönetmeyi ve birbirine yardım etmeyi taahhüt eden bildirgeyi imzaladı. İttifak, Viyana Kongresi düzeninin muhafazakâr dayanağı oldu.","kaynak":"Holy Alliance Treaty metni, Northern Virginia Community College belge derlemesi, https://novaonline.nvcc.edu/eli/evans/HIS241/Documents/RobBeaDocs/HolyAlliance.html (okunan: «signed at Paris, 1815, 14/26th September») · TDV «Rusya» (Kemal Beydilli) bu antlaşmaya gün vermiyor","onem":4,"dunya":3},{"kapsam":"dis","bolge":4,"t":"1879-10-07","k":"antlasma","tur":"antlasma","etiket":["antlasma"],"b":"Zweibund — Alman-Avusturya İttifakı Viyana'da imzalandı","gun":"7 Ekim 1879","yer_id":"Viyana","odak_yer":["Viyana","Berlin"],"d":"Berlin Kongresi'nden sonra Almanya ile Avusturya-Macaristan, Rusya'ya karşı karşılıklı savunma ittifakı kurdu. Andrássy ile Prens Reuss'un imzaladığı gizli antlaşma, 1882'de İtalya'nın katılımıyla Üçlü İttifak'a dönüştü ve 1914'e kadar sürdü.","kaynak":"Avalon Project (Yale Law School), «The Dual Alliance Between Austria-Hungary and Germany», https://avalon.law.yale.edu/19th_century/dualalli.asp (okunan: «Done at Vienna, October 7, 1879»)","onem":4,"dunya":4},{"kapsam":"dis","bolge":4,"t":"1682-05-07","k":"taht","tur":"hanedan","etiket":["siyaset"],"b":"III. Fyodor öldü, I. Petro çar ilan edildi","gun":"7 Mayıs 1682 (Jülyen 27 Nisan)","yer_id":"Moskova","odak_yer":["Moskova"],"d":"Çocuksuz ölen III. Fyodor'un ardından Kremlin'de toplanan zümre temsilcileri on yaşındaki Petro'yu çar ilan etti. Miloslavski tarafının kışkırttığı streltsı ayaklanmasından sonra Petro ile ağabeyi V. İvan ortak çar yapıldı, yönetim naibe Sofya'ya geçti. Petro 1696'dan sonra tek başına hükmetti.","kaynak":"Encyclopaedia Britannica, «Fyodor III», https://www.britannica.com/biography/Fyodor-III (okunan: «died April 27 [May 7], 1682, Moscow») · Britannica, «Peter I», https://www.britannica.com/biography/Peter-the-Great (okunan: Fyodor 1682'de ölünce Kremlin'de toplanan temsilciler Petro'dan yana çıktı, Petro çar ilan edildi — gün vermiyor) · Britannica, «Ivan V» (ortak çarlık: streltsı isyanı 23 Mayıs [2 Haziran] 1682, üç gün sonra duma ikisini ortak çar ilan etti) · TDV «Rusya» (Kemal Beydilli): yalnız yıl 1682; sayfalar 11 Kasım 2026'da açılıp okundu","onem":4,"dunya":3},{"kapsam":"dis","bolge":5,"t":"1881-06-18","k":"antlasma","tur":"antlasma","etiket":["antlasma"],"b":"Üç İmparator Ligi (ikinci) — Boğazlar, Bosna-Hersek ve Doğu Rumeli üzerinde gizli uzlaşma","gun":"18 Haziran 1881","yer_id":"Berlin","odak_yer":["Berlin","Viyana","St. Petersburg"],"d":"Avusturya-Macaristan, Almanya ve Rusya Berlin'de gizli bir antlaşma imzaladı. Taraflar 'Avrupa'daki Türkiye'nin' toprak statükosunun ancak üçünün ortak kararıyla değişebileceğini kabul etti. Boğazların savaş gemilerine kapalılığını ortak ilke saydılar. Ek protokolle Avusturya-Macaristan Bosna-Hersek'i dilediği an ilhak etme hakkını aldı; Bulgaristan ile Doğu Rumeli'nin birleşmesine karşı çıkılmayacağı kararlaştırıldı. Antlaşma 1873'teki ilk ligin yerine geçti, 1884'te yenilendi, 1887'de sona erdi.","kaynak":"Avalon Project (Yale Law School), «The Three Emperors League - June 18, 1881», https://avalon.law.yale.edu/19th_century/empleagu.asp (okunan: md. 2 «territorial status quo of Turkey in Europe», md. 3 Boğazlar, protokol md. 1 Bosna-Hersek, md. 6 «signed on this day at Berlin») · Encyclopaedia Britannica, «Dreikaiserbund», https://www.britannica.com/event/Dreikaiserbund (okunan: «A second one, formal and secret, was established June 18, 1881»); sayfalar 11 Kasım 2026'da açılıp okundu","onem":4,"dunya":4},{"kapsam":"dis","bolge":4,"t":"1894-01-04","k":"antlasma","tur":"antlasma","etiket":["antlasma"],"b":"Fransız-Rus İttifakı resmîleşti","gun":"4 Ocak 1894 (mektup teatisi 27 Aralık 1893 – 4 Ocak 1894)","yer_id":"Paris","odak_yer":["Paris","St. Petersburg"],"d":"Fransa ile Rusya, 1892 askerî sözleşmesinin hükümlerini mektup teatisiyle onaylayarak gizli bir ittifak kurdu. Almanya veya onun desteklediği bir devlet taraflardan birine saldırırsa öteki Almanya'ya karşı bütün gücüyle savaşa girecekti. İttifak Üçlü İttifak sürdükçe geçerliydi ve Birinci Dünya Savaşı'nın blok düzenini kurdu.","kaynak":"Encyclopaedia Britannica, «Dual Alliance» (France-Russia), https://www.britannica.com/topic/Dual-Alliance (okunan: «formalized through an exchange of letters (Dec. 27, 1893–Jan. 4, 1894)») · Avalon Project (Yale), «The Franco-Russian Alliance Military Convention - August 18, 1892», https://avalon.law.yale.edu/19th_century/frrumil.asp (sözleşme metni) · TDV «Rusya» (Kemal Beydilli): askerî antlaşma 1892 (yıl); sayfalar 11 Kasım 2026'da açılıp okundu","onem":4,"dunya":4}];

